fn find_first_occurrence(arr: &Vec<i32>, target: i32) -> Option<usize> {
    let mut left = 0;
    let mut right = arr.len() as isize - 1; // Use isize for easier calculations with indices

    while left <= right {
        let mid = (left + right) / 2; // Calculate the middle index

        if arr[mid as usize] < target {
            left = mid + 1; // Move the left pointer to the right
        } else if arr[mid as usize] > target {
            right = mid - 1; // Move the right pointer to the left
        } else {
            // Found the target, now check for the first occurrence
            if mid == 0 || arr[(mid - 1) as usize] < target {
                return Some(mid as usize); // Return the index if it's the first occurrence
            }
            right = mid - 1; // Continue searching in the left half
        }
    }

    None // Target not found
}